insert into public.lt_competitions (id, slug, name, kind, sport_key, status, stage, country, starts_on, ends_on, summary, about, eligibility, poster_url, bracket_size, playoff_seats, third_place, knockout_popup, knockout_starts_on, points_win, points_draw, points_loss, extra) values ('9654ac17-95fc-42d4-a211-69d0c42e205f', 'christmas-domino-league-2026', '2nd Annual Christmas Domino League', 'hybrid', 'domino', 'published', 'regular', 'Jamaica', '2026-11-30', '2026-12-23', 'A JDCA League thank-you to its most committed players: fourteen teams, a cash prize, and a final on December 23.', '[{"heading":"About the league","body":"The Christmas Domino League was established as a gesture of appreciation to recognise and reward the players who participated in, and showed their commitment and support to, the JDCA League. It is a chance to compete for an attractive cash prize during the festive season."},{"heading":"Our appreciation","body":"More than just another competition: a celebration of commitment, sportsmanship and the players who helped make the JDCA League a success. You supported the league. Now it’s our turn to reward you!"}]'::jsonb, '["Only teams that participated in the JDCA League are eligible.","Each team submits a maximum of nine (9) male and four (4) female players.","Players must have shown commitment and devoted attention to the JDCA League.","Players must not have played in any other domino league of a similar nature."]'::jsonb, null, 32, 4, true, true, '2026-12-21', 3, null, 0, '{"derby_points":2,"derby_max":3,"late_return_penalty":1,"start_time":"7:45 PM","latest_start":"8:00 PM"}'::jsonb);
