insert into public.lt_fixtures (id, competition_id, division_id, stage, round_label, starts_at, venue_id, home_team_id, away_team_id, home_player_id, away_player_id, bracket_slot, status, home_score, away_score, detail) values ('cd20cf6f-9f99-4375-adec-914745aaeb98', '9654ac17-95fc-42d4-a211-69d0c42e205f', '20684394-6fc5-45ca-90bf-49118c039132', 'final', 'Semifinals, Final & Closing Ceremony', '2026-12-23T19:45:00-05:00', '1de03e81-8a68-4a94-9019-73b380d9486e', null, null, null, null, null, 'scheduled', null, null, '{"placeholder":true}'::jsonb);
insert into public.lt_rule_sections (id, competition_id, title, sort) values ('5adf009e-c0bf-47f5-9255-321bc8bbf93b', '9654ac17-95fc-42d4-a211-69d0c42e205f', 'Match format', 0);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('71091403-5a87-4a66-9f54-2a4eb9cb79f0', '5adf009e-c0bf-47f5-9255-321bc8bbf93b', 'All matches will be played at a venue to be announced. Dominoes will be provided, and all matches will be live-streamed.', array[]::text[], null, false, null, 0);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('a90ff8c5-177f-4d85-ac19-1e94daa7b0ae', '5adf009e-c0bf-47f5-9255-321bc8bbf93b', 'The competition will be played in a knockout format until the Final.', array[]::text[], null, false, null, 1);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('78fa8efe-fc52-4628-852a-2b47c8aba7d1', '5adf009e-c0bf-47f5-9255-321bc8bbf93b', 'The first player to reach the target will be declared winner of the set: men play to fifteen (15) points, women play to eleven (11) points.', array[]::text[], 'scoring', true, 'Sets: men to 15, women to 11', 2);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('cc364c8b-3c6d-451b-8cc0-22589550c5df', '5adf009e-c0bf-47f5-9255-321bc8bbf93b', 'Matches will begin at 7:45 p.m. There will be a fifteen (15)-minute grace period. Therefore, all matches MUST begin by 8:00 p.m. SHARP.', array[]::text[], 'schedule', true, '7:45 PM start · 8:00 PM latest', 3);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('42e58ff7-f008-4113-9464-d8709d872f62', '5adf009e-c0bf-47f5-9255-321bc8bbf93b', 'Each team registers nine (9) male and four (4) female players. The defending men’s champion will start at the Second Round.', array[]::text[], null, false, null, 4);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('1d2d5c1c-4ed2-476c-91da-6bafc4be720d', '5adf009e-c0bf-47f5-9255-321bc8bbf93b', 'The team list submitted upon registration is FINAL.', array[]::text[], null, false, null, 5);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('77720cdb-0636-4ad6-a1ed-bbc2a464adef', '5adf009e-c0bf-47f5-9255-321bc8bbf93b', 'Double six MUST be posed to start every game.', array[]::text[], null, true, 'Double six starts every game', 6);
insert into public.lt_rule_sections (id, competition_id, title, sort) values ('2cd8786d-b537-460e-b463-a3e3634632bf', '9654ac17-95fc-42d4-a211-69d0c42e205f', 'Competition format', 1);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('d9575a4e-d3b3-4dfa-b3bf-7be3135466be', '2cd8786d-b537-460e-b463-a3e3634632bf', 'The top eight (8) players from the knockout rounds will advance to the Quarter-Finals.', array[]::text[], 'bracket', false, null, 0);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('4fc41399-5d6c-4332-8add-469afd88327c', '2cd8786d-b537-460e-b463-a3e3634632bf', 'The winners of the Quarter-Finals will advance to the Semi-Finals.', array[]::text[], 'bracket', false, null, 1);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('416020da-0076-4abb-8e2c-a0e3ec770b57', '2cd8786d-b537-460e-b463-a3e3634632bf', 'The winners of the Semi-Finals will contest the Final.', array[]::text[], 'bracket', false, null, 2);
insert into public.lt_rule_sections (id, competition_id, title, sort) values ('0a7596f1-a442-4231-8fbe-17580dcc5ce0', '9654ac17-95fc-42d4-a211-69d0c42e205f', 'Dress code', 2);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('1bb22863-d428-4119-a5e0-cf9c40ce28af', '0a7596f1-a442-4231-8fbe-17580dcc5ce0', 'All players MUST be decently attired when attending matches.', array[]::text[], null, false, null, 0);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('36c3be29-7ec8-4137-b0f4-08ea58587530', '0a7596f1-a442-4231-8fbe-17580dcc5ce0', 'The following will NOT be permitted in the playing area:', array['Vests and marinas','Shorts and short tights','Mini-skirts','Sleeveless clothing','Belly-skin tops','Spaghetti straps','Distressed jeans','Slippers']::text[], null, false, null, 1);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('3fa62497-3561-4422-a5fc-f9f0ff124d9a', '0a7596f1-a442-4231-8fbe-17580dcc5ce0', 'Crocs are permitted, provided they have the back strap secured and are worn with socks. Female players are permitted to wear slippers.', array[]::text[], null, false, null, 2);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('afc5e18c-c8ad-405e-a15e-4625bfe22199', '0a7596f1-a442-4231-8fbe-17580dcc5ce0', 'The exposure of undergarments (panties, boxers or briefs) will NOT be tolerated.', array[]::text[], null, false, null, 3);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('2c3ca8f7-dd8b-42f8-ac28-cb127ca6e27f', '0a7596f1-a442-4231-8fbe-17580dcc5ce0', 'BELTS MUST BE WORN.', array[]::text[], null, true, 'Belts must be worn', 4);
insert into public.lt_rule_sections (id, competition_id, title, sort) values ('1b6732c7-e154-486c-a5dd-6a4de67dbfbf', '9654ac17-95fc-42d4-a211-69d0c42e205f', 'Conduct & behaviour', 3);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('61d980a4-3a37-44d7-90da-e0f1aef7e063', '1b6732c7-e154-486c-a5dd-6a4de67dbfbf', 'Exemplary behaviour is expected at all times from everyone participating in the Christmas Domino League.', array[]::text[], null, false, null, 0);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('83be7444-965c-44aa-a251-930378766645', '1b6732c7-e154-486c-a5dd-6a4de67dbfbf', 'The following conduct is strictly prohibited:', array['Boisterous or disruptive behaviour','Indecent or offensive language','Physical assault and/or verbal abuse of any official, supporter, team member or non-playing member of a participating team','Smoking in or around the playing area']::text[], null, false, null, 1);
insert into public.lt_rule_sections (id, competition_id, title, sort) values ('8958c4ea-1323-4423-ad6a-dce5866d2287', '9654ac17-95fc-42d4-a211-69d0c42e205f', 'Game play', 4);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('79dbc220-241c-4bab-a047-ca720074493c', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'Each player must draw TWO SETS of hands before looking at the dominoes.', array[]::text[], null, false, null, 0);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('f4d0e300-2592-414c-ada0-0a33281c8681', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'If a domino is exposed while drawing, the opponent has the right to request a reshuffle. Players are not permitted to shuffle in a manner that disadvantages their opponents.', array[]::text[], null, false, null, 1);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('32fa8707-1bd8-4554-bd5a-2ab41c0f37ae', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'If a player draws more than seven (7) dominoes in one hand, the opponent MUST be allowed to remove the additional domino(es) and place them in the other hand.', array[]::text[], null, false, null, 2);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('9503e983-048d-41ac-8e20-89c3668069f3', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'If a player draws more than seven (7) dominoes and looks at the hand, the game will automatically be awarded to the opponent.', array[]::text[], 'scoring', false, null, 3);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('cd77b6fd-177f-41a9-98f6-8485fa6bbc57', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'Double six MUST be posed AFTER all four (4) hands have received the required seven (7) dominoes.', array[]::text[], null, false, null, 4);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('7439ccb9-eb75-4fa3-bb20-cccc3b579fec', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'Players are NOT allowed to converse with any individual while a game is in progress.', array['First offence: verbal warning','Second offence: yellow card','Third offence: red card']::text[], 'cards', false, null, 5);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('52ddcdaa-b072-4290-9fb6-7b74b6330739', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'Players are NOT allowed to look at both hands simultaneously.', array['First offence: verbal warning','Second offence: yellow card','Third offence: red card']::text[], 'cards', false, null, 6);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('4af4aadb-e8c9-421c-a956-64f4f036770a', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'A knock is NOT a pass. If a player has no legitimate play, he or she MUST clearly say “PASS”.', array[]::text[], null, false, null, 7);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('56fe257a-d462-4d61-a067-3d63f5cb99d7', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'Players are NOT allowed to read or ask Cards Around when passing. They should simply say “PASS” and allow the game to continue.', array['First offence: verbal warning','Second offence: the game will be awarded to the opponent']::text[], 'scoring', false, null, 8);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('ca731e2d-21c7-4167-a0bd-65c13558879e', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'Time-wasting will NOT be permitted. Each player has twenty (20) seconds to play a domino. If a player fails to play in time, the referee MUST be called and will count the player down to three (3); if the player has still not played, a yellow card is issued. Two (2) yellow cards in the same match result in a red card: the player must leave the ring and may not play for the rest of the set.', array[]::text[], 'cards', true, '20 seconds per play', 9);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('8f29fdfb-462f-43d0-ab25-09c1b8143cc8', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'A ONE-AWAY is awarded ONLY when a player takes an unnecessary pass (says “PASS” despite having a legitimate play). Once a player says “PASS” while having a legitimate play, the game will be awarded to the opponent.', array[]::text[], 'scoring', false, null, 10);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('29782d53-18b1-46e7-9e7a-667ec7eb22da', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'Blocked games: when no further legitimate plays can be made and unplayed dominoes remain, the dots on all unplayed dominoes are counted. After the last legitimate play the player MUST immediately expose the remaining dominoes (announcing “BLOCKED” is optional), and ALL hands MUST be exposed. The player with the lowest individual total wins the game. If the lowest scores on each side are tied, it is declared a “DERBY”: the following game is the Derby game, worth two (2) game points to the winner; a double/triple Derby earns a maximum of three (3) game points.', array[]::text[], 'scoring', true, 'Derby games: 2 points', 11);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('da917ded-6cd1-4f4a-8afd-9e1600a23264', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'If a player plays from the wrong hand, the game will be awarded to the opponent.', array[]::text[], 'scoring', false, null, 12);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('77921912-f7ae-4392-a36a-f4716dda676d', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'A player MUST allow the opponent to concede the game before pulling it up. The opponent MUST be allowed to see how the game was lost and acknowledge the loss. Players are encouraged to concede when they recognise they have lost. If a player declares their hands and dictates the game but the opponent refuses to concede, the referee MUST be called.', array[]::text[], null, false, null, 13);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('620e0533-eab8-43c5-a3d3-42870af3f638', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'Celebrations and physical contact: no player may touch another player while celebrating. Dominoes is a no-contact sport. Dominoes must not come into contact with anyone, and players may not strike the table so that all the dominoes are knocked off.', array[]::text[], null, false, null, 14);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('4d01a45a-1efd-4cc6-8e05-a85ec8f91e6d', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'A change of dominoes may ONLY be requested if there is a visible mark noticeable enough to give an opponent an unfair advantage.', array[]::text[], null, false, null, 15);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('23b67cca-5605-4fe4-829c-211178b6fb48', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'Cheating is strictly prohibited. Any player caught cheating or found guilty of cheating will be expelled from the playing arena.', array[]::text[], null, false, null, 16);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('6d9cd409-5b42-4f35-8f62-a1a7eadceb25', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'Players are allowed a MAXIMUM of TWO (2) bathroom breaks per set. If a player fails to return within five (5) minutes, one (1) point will be awarded to the opponent.', array[]::text[], 'scoring', false, null, 17);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('445e6284-6f4b-4a70-a66c-d4e9e7c1658d', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'If a player receives a red card and is asked to leave the ring, the remaining points in the set will be awarded to the opponent.', array[]::text[], 'scoring', false, null, 18);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('39c4eed8-911e-4604-9f11-f207e1c235db', '8958c4ea-1323-4423-ad6a-dce5866d2287', 'If a player has not won a game in the set and chooses not to complete it, the remaining points will be awarded to the opponent.', array[]::text[], 'scoring', false, null, 19);
insert into public.lt_rule_sections (id, competition_id, title, sort) values ('f661f7c6-635b-448d-80aa-daa00fc2ecc0', '9654ac17-95fc-42d4-a211-69d0c42e205f', 'After winning your set', 5);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('2f8eaaf1-260c-4a38-8d09-468687af1df7', 'f661f7c6-635b-448d-80aa-daa00fc2ecc0', 'A player MUST exit the ring once he or she has completed their game, allowing the remaining tables to complete their match.', array[]::text[], null, false, null, 0);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('6a7dec94-f57e-472b-893c-865a7ab6f013', 'f661f7c6-635b-448d-80aa-daa00fc2ecc0', 'In a Derby game, when a player needs one (1) point to win, the game is played for that one point.', array[]::text[], 'scoring', false, null, 1);
insert into public.lt_rule_sections (id, competition_id, title, sort) values ('7d56fc18-349e-44f0-938d-170b83775185', '9654ac17-95fc-42d4-a211-69d0c42e205f', 'Miscellaneous', 6);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('b9e8dc56-1ee9-4a0b-9f8e-48f9414c0d4f', '7d56fc18-349e-44f0-938d-170b83775185', 'Every player MUST present a valid government-issued ID for verification before being allowed to participate. A player without an ID must present a photograph signed by a Justice of the Peace (JP).', array[]::text[], null, false, null, 0);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('95df7e75-bfe1-4a06-b4f7-57b4679d1199', '7d56fc18-349e-44f0-938d-170b83775185', 'All matches will be live-streamed.', array[]::text[], null, false, null, 1);
insert into public.lt_rules (id, section_id, body, bullets, tag, highlight, chip_label, sort) values ('bdedbb12-9792-4abf-9a77-c4478d81991a', '7d56fc18-349e-44f0-938d-170b83775185', 'THE REFEREE’S DECISION IS FINAL.', array[]::text[], null, false, null, 2);
